    private void tblClientesMouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_tblClientesMouseClicked
        int fila = tblClientes.getSelectedRow();

if (fila >= 0) {

    txtIdCliente.setText(
        tblClientes.getValueAt(fila, 0).toString()
    );

    txtNombre.setText(
        tblClientes.getValueAt(fila, 1).toString()
    );

    txtTelefono.setText(
        tblClientes.getValueAt(fila, 2) == null
            ? ""
            : tblClientes.getValueAt(fila, 2).toString()
    );

    txtCorreo.setText(
        tblClientes.getValueAt(fila, 3) == null
            ? ""
            : tblClientes.getValueAt(fila, 3).toString()
    );

    txtDireccion.setText(
        tblClientes.getValueAt(fila, 4) == null
            ? ""
            : tblClientes.getValueAt(fila, 4).toString()
    );
}
    }//GEN-LAST:event_tblClientesMouseClicked

    private void btnLimpiarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLimpiarActionPerformed
txtIdCliente.setText("");
txtNombre.setText("");
txtTelefono.setText("");
txtCorreo.setText("");
txtDireccion.setText("");

tblClientes.clearSelection();

txtNombre.requestFocus();
    }//GEN-LAST:event_btnLimpiarActionPerformed

    private void btnGuardarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnGuardarActionPerformed
        String nombre = txtNombre.getText().trim();
String telefono = txtTelefono.getText().trim();
String correo = txtCorreo.getText().trim();
String direccion = txtDireccion.getText().trim();

if (nombre.isEmpty()) {
    JOptionPane.showMessageDialog(this,
            "Debe ingresar el nombre del cliente.");
    txtNombre.requestFocus();
    return;
}

Cliente cliente = new Cliente();

cliente.setNombre(nombre);
cliente.setTelefono(telefono);
cliente.setCorreo(correo);
cliente.setDireccion(direccion);

if (clienteDAO.insertar(cliente)) {

    JOptionPane.showMessageDialog(this,
            "Cliente registrado correctamente.");

    mostrarClientes();

    txtIdCliente.setText("");
    txtNombre.setText("");
    txtTelefono.setText("");
    txtCorreo.setText("");
    txtDireccion.setText("");

    tblClientes.clearSelection();
    txtNombre.requestFocus();

} else {

    JOptionPane.showMessageDialog(this,
            "Error al registrar el cliente.",
            "Error",
            JOptionPane.ERROR_MESSAGE);
}
    }//GEN-LAST:event_btnGuardarActionPerformed

    private void btnEditarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnEditarActionPerformed
        try {

    if (txtIdCliente.getText().trim().isEmpty()) {
        JOptionPane.showMessageDialog(this,
                "Seleccione un cliente de la tabla para editar.");
        return;
    }

    String nombre = txtNombre.getText().trim();
    String telefono = txtTelefono.getText().trim();
    String correo = txtCorreo.getText().trim();
    String direccion = txtDireccion.getText().trim();

    if (nombre.isEmpty()) {
        JOptionPane.showMessageDialog(this,
                "Debe ingresar el nombre del cliente.");
        txtNombre.requestFocus();
        return;
    }

    int idCliente = Integer.parseInt(
            txtIdCliente.getText().trim()
    );

    Cliente cliente = new Cliente();

    cliente.setIdCliente(idCliente);
    cliente.setNombre(nombre);
    cliente.setTelefono(telefono);
    cliente.setCorreo(correo);
    cliente.setDireccion(direccion);

    int confirmar = JOptionPane.showConfirmDialog(
            this,
            "¿Desea guardar los cambios de este cliente?",
            "Confirmar edición",
            JOptionPane.YES_NO_OPTION
    );

    if (confirmar != JOptionPane.YES_OPTION) {
        return;
    }

    if (clienteDAO.actualizar(cliente)) {

        JOptionPane.showMessageDialog(this,
                "Cliente actualizado correctamente.");

        mostrarClientes();

        txtIdCliente.setText("");
        txtNombre.setText("");
        txtTelefono.setText("");
        txtCorreo.setText("");
        txtDireccion.setText("");

        tblClientes.clearSelection();
        txtNombre.requestFocus();

    } else {

        JOptionPane.showMessageDialog(this,
                "Error al actualizar el cliente.",
                "Error",
                JOptionPane.ERROR_MESSAGE);
    }

} catch (NumberFormatException e) {

    JOptionPane.showMessageDialog(this,
            "El ID del cliente no es válido.",
            "Error",
            JOptionPane.ERROR_MESSAGE);
}
    }//GEN-LAST:event_btnEditarActionPerformed

    private void btnEliminarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnEliminarActionPerformed
        try {

    if (txtIdCliente.getText().trim().isEmpty()) {

        JOptionPane.showMessageDialog(this,
                "Seleccione un cliente de la tabla para eliminar.");
        return;
    }

    int idCliente = Integer.parseInt(
            txtIdCliente.getText().trim()
    );

    String nombre = txtNombre.getText().trim();

    int confirmar = JOptionPane.showConfirmDialog(
            this,
            "¿Está seguro de eliminar al cliente " + nombre + "?",
            "Confirmar eliminación",
            JOptionPane.YES_NO_OPTION,
            JOptionPane.WARNING_MESSAGE
    );

    if (confirmar != JOptionPane.YES_OPTION) {
        return;
    }

    if (clienteDAO.eliminar(idCliente)) {

        JOptionPane.showMessageDialog(this,
                "Cliente eliminado correctamente.");

        mostrarClientes();

        txtIdCliente.setText("");
        txtNombre.setText("");
        txtTelefono.setText("");
        txtCorreo.setText("");
        txtDireccion.setText("");

        tblClientes.clearSelection();
        txtNombre.requestFocus();

    } else {

        JOptionPane.showMessageDialog(this,
                "No se pudo eliminar el cliente.",
                "Error",
                JOptionPane.ERROR_MESSAGE);
    }

} catch (NumberFormatException e) {

    JOptionPane.showMessageDialog(this,
            "El ID del cliente no es válido.",
            "Error",
            JOptionPane.ERROR_MESSAGE);
}
    }//GEN-LAST:event_btnEliminarActionPerformed

    private void btnVolverActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnVolverActionPerformed
        java.awt.Container contenedor = getParent();

while (contenedor != null) {

    if ("pnlContenido".equals(contenedor.getName())) {

        contenedor.removeAll();
        contenedor.setLayout(new java.awt.BorderLayout());

        contenedor.add(
            new PnlClientesRecetas(),
            java.awt.BorderLayout.CENTER
        );

        contenedor.revalidate();
        contenedor.repaint();

        break;
    }

    contenedor = contenedor.getParent();
}
    }//GEN-LAST:event_btnVolverActionPerformed
private void mostrarClientes() {

    DefaultTableModel modelo = (DefaultTableModel) tblClientes.getModel();

    modelo.setRowCount(0);

    for (Cliente cliente : clienteDAO.listar()) {

        Object[] fila = {
            cliente.getIdCliente(),
            cliente.getNombre(),
            cliente.getTelefono(),
            cliente.getCorreo(),
            cliente.getDireccion()
        };

        modelo.addRow(fila);
    }
}

